import sys, math, pandas as pd
from datetime import timedelta, datetime, timezone
from zoneinfo import ZoneInfo
from collections import defaultdict
week = sys.argv[1]; sched_path = sys.argv[2] if len(sys.argv) > 2 else '/app/out/northwind/schedule.csv'
Z = ZoneInfo('America/Chicago')
def tr(v, sec, aht): return v / sec * aht
def sl(a, n, aht, t):
    if a <= 0: return 1.0
    if n <= a: return 0.0
    term = 1.0; s = 1.0
    for k in range(1, n): term *= a / k; s += term
    term *= a / n; top = term * n / (n - a); pw = top / (s + top)
    return 1 - pw * math.exp(-(n - a) * t / aht)
def req(v, aht, tgt, t):
    a = tr(v, 1800, aht)
    if a <= 0: return 0
    n = max(1, math.ceil(a))
    while not (sl(a, n, aht, t) >= tgt and a / n <= 0.85): n += 1
    return n
SLA = {'priority': (0.9, 30), 'standard': (0.8, 20), 'vip': (0.9, 20)}
HRS = {'priority': (6, 24), 'standard': (6, 24), 'vip': (8, 20)}
df = pd.read_csv(f'/app/data/northwind/export_{week}.csv')
df['t'] = pd.to_datetime(df.interval_start_local + df.utc_offset, format='%Y-%m-%d %H:%M%z', utc=True).dt.floor('30min')
y, w = week.split('-W'); mon = datetime.fromisocalendar(int(y), int(w), 1)
st = mon.replace(tzinfo=Z).astimezone(timezone.utc); en = (mon + timedelta(days=7)).replace(tzinfo=Z).astimezone(timezone.utc)
grid = list(pd.date_range(st, en, freq='30min', inclusive='left'))
def lh(t): l = t.astimezone(Z); return l.hour + l.minute / 60
R = {}
for r in df.itertuples():
    lo, hi = HRS[r.queue]
    R[(r.queue, r.t)] = req(r.volume, r.aht_sec, *SLA[r.queue]) if lo <= lh(r.t) < hi else 0
s = pd.read_csv(sched_path)
for c in ('segment_start_utc', 'segment_end_utc', 'break_start_utc'): s[c] = pd.to_datetime(s[c], utc=True)
ag = pd.read_csv('/app/data/agents/northwind.csv').set_index('agent_id')
gross = defaultdict(int); brk = defaultdict(int)
for r in s.itertuples():
    for t in grid:
        if r.segment_start_utc <= t < r.segment_end_utc:
            gross[(r.queue, t)] += 1
            if r.break_minutes and r.break_start_utc < t + timedelta(minutes=30) and t < r.break_start_utc + timedelta(minutes=int(r.break_minutes)):
                brk[(r.queue, t)] += 1
