under = 0
for q in SLA:
    ops = [t for t in grid if HRS[q][0] <= lh(t) < HRS[q][1]]
    out[f'sla_attainment_{q}'] = round(sum(net(q, t) >= R.get((q, t), 0) for t in ops) / len(ops), 3)
    under += sum(max(0, R.get((q, t), 0) - net(q, t)) for t in grid) * 0.5
hours = ((s.segment_end_utc - s.segment_start_utc).dt.total_seconds() / 3600).sum()
reqh = sum(R.values()) * 0.5
out.update(scheduled_hours_total=round(hours, 1), required_hours_total=round(reqh, 1), ratio=round(hours / reqh, 4),
           understaffed_interval_hours=round(under, 1), agents_scheduled=s.agent_id.nunique())
