v = defaultdict(list)
s['day'] = s.segment_start_utc.map(lambda t: t.astimezone(Z).date())
shifts = s.groupby(['agent_id', 'day'])
caps = {'FT': 40, 'PT': 24}
for aid, g in s.groupby('agent_id'):
    a = ag.loc[aid]; sk = a.skills.split(';')
    if (~g.queue.isin(sk)).any(): v['skill'].append(aid)
    h = ((g.segment_end_utc - g.segment_start_utc).dt.total_seconds() / 3600).sum()
    if h > caps[a.contract] + 1e-9: v['hours'].append((aid, h))
    gg = g.sort_values('segment_start_utc')
    if (gg.segment_start_utc.iloc[1:].values < gg.segment_end_utc.iloc[:-1].values).any(): v['overlap'].append(aid)
    days = sorted(set(g.day)); run = 1
    for d1, d2 in zip(days, days[1:]):
        run = run + 1 if (d2 - d1).days == 1 else 1
        if run > 5: v['consec'].append(aid)
    sh = g.groupby('day').agg(st=('segment_start_utc', 'min'), en=('segment_end_utc', 'max'), n=('segment_idx', 'count'), q=('queue', 'nunique')).sort_index()
    for (d1, r1), (d2, r2) in zip(sh.iterrows(), list(sh.iterrows())[1:]):
        if r2.st - r1.en < timedelta(hours=11): v['rest'].append((aid, d1, d2, r2.st - r1.en))
    for d, r in sh.iterrows():
        if r.n > 1 and a.contract != 'PT': v['split'].append((aid, d))
        if r.q > 1: v['multi_queue_day'].append((aid, d))
for (aid, d), g in shifts:
    tid = g.template_id.iloc[0]
    if tid not in ('E8', 'D8', 'L8', 'N8', 'P6a', 'P6b', 'P4', 'S44'): v['template'].append(tid)
    l0 = g.segment_start_utc.min().astimezone(Z); l1 = g.segment_end_utc.max().astimezone(Z)
    if l1.date() != l0.date() and not (l1.hour == 0 and l1.minute == 0): v['midnight'].append(aid)
    hours = ((g.segment_end_utc - g.segment_start_utc).dt.total_seconds() / 3600).sum()
    b = g[g.break_minutes > 0]
    if hours >= 6:
        if len(b) != 1 or int(b.break_minutes.iloc[0]) != 20: v['break_count'].append((aid, d)); continue
        bs = b.break_start_utc.iloc[0]; s0 = g.segment_start_utc.min(); q = g.queue.iloc[0]
        if not (s0 + timedelta(hours=2) <= bs <= s0 + timedelta(hours=5)): v['break_window'].append((aid, d)); continue
        if not any(r.segment_start_utc <= bs and bs + timedelta(minutes=20) <= r.segment_end_utc for r in g.itertuples()): v['break_outside'].append((aid, d))
        cand = [t for t in grid if s0 + timedelta(hours=2) <= t <= s0 + timedelta(hours=5) and any(r.segment_start_utc <= t < r.segment_end_utc for r in g.itertuples())]
        sur = {t: gross[(q, t)] - R.get((q, t), 0) for t in cand}
        bi = bs.floor('30min')
        if sur.get(bi, -99) < max(sur.values()): v['break_surplus'].append((aid, d, bi, sur.get(bi), max(sur.values())))
        # exclusive-5h variant
        cand2 = [t for t in cand if t < s0 + timedelta(hours=5)]
        if cand2 and sur.get(bi, -99) < max(sur[t] for t in cand2) or bi not in cand2: v['break_surplus_excl5h'].append((aid, d))
    elif len(b): v['break_on_short'].append((aid, d))
for t in grid:
    if 6 <= lh(t) < 24:
        if net('vip', t) < 1: v['vip_net'].append(t)
        if gross[('vip', t)] < 1: v['vip_gross'].append(t)
print(out)
print({k: len(x) for k, x in v.items()})
for k, x in v.items():
    if k not in ('break_surplus_excl5h',): print(k, x[:5])
