# DP over days: total shifts <= 55, hours <= 440
dp = {(0, 0): 0}
for d in days:
    nd = {}
    for (k, h), f in dp.items():
        for kk, v in res[d].items():
            if v is None: continue
            (fail, hrs), _ = v
            key = (k + kk, h + hrs)
            if key[0] <= 55 and key[1] <= 440 and nd.get(key, 1e9) > f + fail: nd[key] = f + fail
    dp = nd
best = min(dp.values()); ops = sum(op)
print('BOUND fails', best, 'of', ops, 'attainment', round(1 - best / ops, 3))
EOF
cd /app; for w in 2026-W42 2026-W43 2026-W44; do (timeout 1500 python /tmp/nw/vipbound.py $w 2>/dev/null | grep BOUND > /tmp/nw/bound_$w.txt &) ; done; echo started

